'use strict';
// Explicit body-only amendments for eight demonstrated transfer findings.
// Accepted single dialogue/rating records stay frozen; generated pairs stay drafts.
const path=require('node:path'),assert=require('node:assert/strict'),c=require('./core.cjs');
const keys=['S95','S96','S99','S167','S168','S235','S236','S238'],fields=['action','opening','response','challenge','closing'];
function bodyInvariant(before,after){const b=structuredClone(before),a=structuredClone(after);for(const f of fields){assert.equal(typeof a[f],'string');assert.ok(a[f].length>8);assert.deepEqual((a[f].match(/\{[^}]+\}/g)||[]).sort(),(b[f].match(/\{[^}]+\}/g)||[]).sort(),'Transfer slots changed');delete a[f];delete b[f];}assert.deepEqual(a,b,'Transfer identity, hashes or status changed');assert.notEqual(c.hash(before),c.hash(after),'Empty transfer amendment');}
function scope(spec){assert.equal(spec.schema,3);assert.ok(keys.includes(spec.key),'Undemonstrated transfer scope');assert.equal(spec.beforeTransfer.cardId,spec.key);assert.equal(c.hash(spec.beforeTransfer),spec.beforeTransferHash);assert.equal(c.hash(spec.afterTransfer),spec.afterTransferHash);bodyInvariant(spec.beforeTransfer,spec.afterTransfer);assert.deepEqual(spec.selectedIds,[spec.key+'-single-a',spec.key+'-single-b']);assert.ok(spec.authorAssessment.length>=40&&/A1/.test(spec.authorAssessment)&&/A3/.test(spec.authorAssessment));return spec;}
function blind(input,writer,spec){scope(spec);const raw=input.bindings.find(x=>x.key===spec.key);assert.ok(raw);assert.deepEqual(raw.transfer,spec.beforeTransfer);assert.equal(raw.bespokePairs.length,0,'Bespoke pairs require separate provenance scope');const rows=input.records.filter(r=>r.key===spec.key);assert.equal(rows.length,2);assert.deepEqual(rows.map(r=>r.exampleId).sort(),spec.selectedIds.slice().sort());return {rubric:c.rubric,records:[],bindings:[{key:spec.key,card:rows[0].card,transfer:spec.afterTransfer,originalTransfer:spec.beforeTransfer,bespokePairs:[],supportingSeeds:[],candidateDialogues:rows.map(r=>({exampleId:r.exampleId,card:r.card,originalDialogue:r.before.beats,beats:writer.records.find(w=>w.exampleId===r.exampleId).beats})),scope:'Fresh binding-only review of an explicit transfer-body amendment. Read the exact card, both original and accepted candidate single dialogues, and every original/proposed transfer field. Are the proposed fields faithful to the exact mechanism and their described source material? Identify real residual contradictions or unsupported details. Seed hashes still describe the historical originals; validated integration will bind the accepted dialogue only after your compatibility assessment. A compiled transfer is not an individually reviewed pair. Do not score single or pair dialogue; records must be empty. No writer scores or improvement claims are supplied.'}]};}
function derive(input,writer,review,spec,bindingReview){scope(spec);c.validateWriter(input,writer);c.validateReview(c.reviewerInput(input,writer),review);assert.ok([...writer.bindings,...review.bindings].some(b=>b.key===spec.key&&!b.compatible),'No demonstrated hold');for(const id of spec.selectedIds)assert.ok(review.records.find(r=>r.exampleId===id)?.accept,'Unaccepted scene cannot use binding recovery');const expected=blind(input,writer,spec);c.validateReview(expected,bindingReview);assert.equal(bindingReview.records.length,0);assert.ok(bindingReview.bindings.every(b=>b.compatible),'Fresh binding review rejected transfer amendment');const result={input:structuredClone(input),writer:structuredClone(writer),review:structuredClone(review)};result.writer.bindings=result.writer.bindings.map(b=>b.key===spec.key?{key:b.key,compatible:true,assessment:spec.authorAssessment}:b);result.review.bindings=result.review.bindings.map(b=>b.key===spec.key?bindingReview.bindings[0]:b);assert.deepEqual(result.writer.records,writer.records);assert.deepEqual(result.review.records,review.records);require('./per-example.cjs').assertSelection(result.input,result.writer,result.review,spec.selectedIds);return result;}
function expectedApplied(spec,writer){scope(spec);return {...structuredClone(spec.afterTransfer),seedBindingHashes:spec.selectedIds.map(id=>{const r=writer.records.find(r=>r.exampleId===id);assert.ok(r);return c.hash(r.beats);})};}
function applySource(root,spec,writer){const file=path.join(root,'examples/authoring/stance-transfers.json'),doc=c.read(file),current=doc.records[spec.key],expected=expectedApplied(spec,writer);assert.deepEqual(current,{...spec.beforeTransfer,seedBindingHashes:expected.seedBindingHashes},'Staged transfer differs from original body plus validated seed binding');doc.records[spec.key]=expected;c.save(file,doc);}
function assertApplied(root,spec){scope(spec);const current=c.read(path.join(root,'examples/authoring/stance-transfers.json')).records[spec.key];assert.deepEqual({...current,seedBindingHashes:spec.afterTransfer.seedBindingHashes},spec.afterTransfer,'Applied transfer body or identity differs from reviewed amendment');const singles=c.read(path.join(root,'examples/authoring/single-scenes.json')).records[spec.key].examples;assert.deepEqual(current.seedBindingHashes,spec.selectedIds.map(id=>c.hash(singles.find(s=>s.id===id).beats)),'Applied transfer seed bindings differ from canonical singles');}
module.exports={keys,fields,scope,bodyInvariant,blind,derive,expectedApplied,applySource,assertApplied};

