function deriveTotals(raw,role){const output=structuredClone(raw),adjustments=[];for(const r of output.records||[]){const pass=r[role==='writer'?'firstPass':'secondPass'];if(!pass||typeof pass.weightedTotal!=='number'||!Number.isFinite(pass.weightedTotal)||!rubric.criteria.every(c=>Number.isInteger(pass.ratings?.[c.id]?.score)&&pass.ratings[c.id].score>=0&&pass.ratings[c.id].score<=5))continue;const expected=require('../coach-review-core.cjs').total(pass);if(pass.weightedTotal!==expected){adjustments.push({exampleId:r.exampleId,field:role==='writer'?'firstPass.weightedTotal':'secondPass.weightedTotal',from:pass.weightedTotal,to:expected});pass.weightedTotal=expected;}}return {output,adjustments};}
